// Decides whether the Shopify order is a wholesale order and builds the alert.
const settings = $('Settings').first().json;
const order = $('Shopify Trigger').first().json;

const tag = String(settings.wholesaleTag || '').trim().toLowerCase();
const splitTags = (t) => (Array.isArray(t) ? t : String(t || '').split(','))
  .map((x) => String(x).trim().toLowerCase())
  .filter(Boolean);

const customer = order.customer || {};
// Shopify no longer includes customer tags or company names in order webhooks, so they come from the lookup.
const lookup = ($('Look up customer and company').first()?.json?.data?.order) || {};
const customerTags = splitTags(lookup.customer?.tags ?? customer.tags);
const purchasing = lookup.purchasingEntity || {};
const orderTags = splitTags(order.tags);
const company = order.company || null;

const reasons = [];
if (settings.treatB2BCompanyOrdersAsWholesale && company) reasons.push('B2B company order');
if (tag && customerTags.includes(tag)) reasons.push(`customer tagged "${tag}"`);
if (tag && orderTags.includes(tag)) reasons.push(`order tagged "${tag}"`);

const total = Number(order.current_total_price ?? order.total_price ?? 0);
const isWholesale = reasons.length > 0 && total >= Number(settings.minimumOrderValue || 0);

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const money = (v) => `${Number(v || 0).toFixed(2)} ${order.currency || ''}`.trim();
const name = [customer.first_name, customer.last_name].filter(Boolean).join(' ') || customer.email || 'Unknown customer';
const companyName = company
  ? [purchasing.company?.name || company.name || `Company #${company.id}`, purchasing.location?.name].filter(Boolean).join(' – ')
  : '';
const shopDomain = (order.order_status_url || '').split('/')[2] || '';
const adminUrl = shopDomain ? `https://${shopDomain}/admin/orders/${order.id}` : '';

const rows = (order.line_items || []).map((li) =>
  `<tr><td>${esc(li.title)}${li.variant_title ? ' – ' + esc(li.variant_title) : ''}</td><td>${esc(li.sku)}</td><td align="right">${li.quantity}</td><td align="right">${money(li.price)}</td></tr>`
).join('');

const subject = `[${settings.storeName}] Wholesale order ${order.name}: ${money(total)}${companyName ? ' · ' + companyName : ''}`;
const html = `
<h2>New wholesale order ${esc(order.name)}</h2>
<p><b>Customer:</b> ${esc(name)}${customer.email ? ' &lt;' + esc(customer.email) + '&gt;' : ''}<br>
${companyName ? `<b>Company:</b> ${esc(companyName)}<br>` : ''}
<b>Total:</b> ${money(total)}<br>
<b>Payment status:</b> ${esc(order.financial_status)}${order.payment_terms ? ' (' + esc(order.payment_terms.payment_terms_name) + ')' : ''}<br>
<b>Why flagged:</b> ${esc(reasons.join(', '))}</p>
<table border="1" cellpadding="6" cellspacing="0"><tr><th>Item</th><th>SKU</th><th>Qty</th><th>Price</th></tr>${rows}</table>
${order.note ? `<p><b>Order note:</b> ${esc(order.note)}</p>` : ''}
${adminUrl ? `<p><a href="${adminUrl}">Open order in Shopify admin</a></p>` : ''}
<p style="color:#888;font-size:12px">Sent by your n8n wholesale order alert.</p>`;

return [{ json: {
  isWholesale,
  reasons,
  orderName: order.name,
  total,
  currency: order.currency,
  customerName: name,
  companyName,
  subject,
  html,
  alertTo: settings.alertTo,
  alertFrom: settings.alertFrom,
} }];
